import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetInfoKey, useCurrentSheet } from './session';
import type { SheetInfo } from './session';

/**
 * The active sheet's today (yyyy-MM-dd), or '' while it loads. Every date-dependent decision and
 * every default date on screen uses this — never `new Date()`.
 */
export function useSheetToday(): string {
  const [sheet] = useCurrentSheet();
  const info = useQuery({
    queryKey: sheetInfoKey(sheet),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}`),
    enabled: !!sheet,
  });
  return info.data?.today ?? '';
}
import { isOpen } from '../claims/claims';
import type { Claim } from '../claims/claims';

/** Whether a claim is overdue: it is OPEN (or PENDING) and its due-by, fixed when it was created, is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return isOpen(claim) && today !== '' && claim.dueBy < today;
}

/** How many full 30-day periods a claim is overdue on the sheet's today: 0 unless it is overdue. */
export function latePeriods(claim: Claim, today: string): number {
  if (!overdue(claim, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${claim.dueBy}T00:00:00Z`)) / 86_400_000;
  return Math.floor(Math.round(days) / 30);
}
import type { Claim } from '../claims/claims';
import { useSheetToday } from '../session/sheetToday';
import { overdue } from './overdue';

// Whether a claim is overdue: OPEN (or PENDING), with its due-by before the sheet's today.
export function ClaimOverdue({ claim }: { claim: Claim }) {
  const today = useSheetToday();
  return <span data-testid="claim-overdue">{overdue(claim, today) ? 'yes' : 'no'}</span>;
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { HomeMain } from '../../slots/defs/homeMain';
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { ClaimDueBy } from './ClaimDueBy';
import { ClaimOverdue } from './ClaimOverdue';
import { OverdueTotals } from './OverdueTotals';
import { PersonOverdueCount, PersonOverdueTotal } from './PersonOverdue';

export const contributions = [
  PersonColumnHeads.fill({ order: 16, Component: () => <th>Overdue</th> }),
  PersonColumns.fill({ order: 16, Component: PersonOverdueCount }),
  PersonColumnHeads.fill({ order: 17, Component: () => <th>Overdue total</th> }),
  PersonColumns.fill({ order: 17, Component: PersonOverdueTotal }),
  ClaimRowValues.fill({ order: 12, Component: ClaimDueBy }),
  ClaimRowValues.fill({ order: 13, Component: ClaimOverdue }),
  HomeMain.fill({ order: 45, Component: OverdueTotals }),
];
# Change a claim's status: open (DRAFT -> OPEN), settle (OPEN -> SETTLED), approve (PENDING -> SETTLED),
# reject (PENDING -> OPEN, with the body's reason) or void (DRAFT, OPEN or PENDING -> VOID).
