import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { claimed, holdsById, useClaims } from './claims';

// The sheet's claimed-total: everyone's counting claims added up (open ones a hold covers left out).
export function ClaimedTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = useClaims();
  const people = usePeople().data ?? [];

  if (!user || !sheet) return null;

  return (
    <p>
      Claimed total: <strong data-testid="rollup-claimed-total">{claimed(claims.data ?? [], holdsById(people))}</strong>
    </p>
  );
}
import type { Person } from '../people/people';
import { claimed, holdsById, useClaims } from './claims';

// What a person has claimed: the sum of their counting claims' amounts (not their open ones a hold covers).
export function PersonClaimed({ person }: { person: Person }) {
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  return <td data-testid="person-claimed">{claimed(claims, holdsById([person]))}</td>;
}
import type { Claim } from '../claims/claims';

// A claim's due-by: fixed when it was created, from the terms of its person's grade in force on its date.
export function ClaimDueBy({ claim }: { claim: Claim }) {
  return <span data-testid="claim-due-by">{claim.dueBy}</span>;
}
